  getr regs 16 = Z_to_bv 64 15 -> getr regs 17 = Z_to_bv 64 1024 -> getr regs 5 = Z_to_bv 64 16 -> getr regs 6 = Z_to_bv 64 17 -> getr regs 7 = Z_to_bv 64 512 ->
  4096 <= ca -> ca + 4096 < 2 ^ 64 -> wrA M ca 2592 ->
